sigjmp_buf env;

const int SAVE_MASK = 1; // Non-zero to save signal mask

// Initial call returns 0, saves environment and mask
int result = sigsetjmp(env, SAVE_MASK);

if (result == 0) {
    // Standard execution path
    // Handler will call siglongjmp(env, 99);
} else {
    // Jumped here (result == 99)
    // Execution context restored
    // Signal mask is fully restored
}
